  if let Some(admission)=self.admission.as_mut(){if admission.terminal_is_empty(){self.admission.take();work+=1;return Ok(RetainedCloneStep::Progress(paid(d)))}let step=take_work!(work,admission.close_step(&mut effect.reborrow(g,effect.maximum_work_units()).expect("retirement child exceeds original effect")));return Ok(RetainedCloneStep::Progress(step.progress()))}
  if let Some(prep)=self.preparation.as_mut(){if prep.terminal_is_empty(){self.preparation.take();work+=1;return Ok(RetainedCloneStep::Progress(paid(d)))}let step=take_work!(work,prep.close_step(&mut effect.reborrow(g,effect.maximum_work_units()).expect("retirement child exceeds original effect")));return Ok(RetainedCloneStep::Progress(step.progress()))}
  if let Some(index)=self.index.as_mut(){if index.terminal_is_empty(){*self.index=None;work+=1;return Ok(RetainedCloneStep::Progress(paid(d)))}let step=take_work!(work,index.close_step(&mut effect.reborrow(g,effect.maximum_work_units()).expect("retirement child exceeds original effect")));return Ok(RetainedCloneStep::Progress(step.progress()))}
  if let Some(admission)=self.source_admission.as_mut(){let mut returned=None;let turn=admission.return_inputs(&mut returned,effect);work+=turn.work;if let Some((raw,()))=returned{*self.raw=Some(raw);}if admission.terminal_is_empty(){self.source_admission.take();}return turn.result.map(|step|RetainedCloneStep::Progress(step.progress())).map_err(Into::into)}
